function KeyLab.GearLootDatabase.GetItemsForSpecSource(specID, sourceID)
    local ids = KeyLab.GearLootDatabase.bySpec and KeyLab.GearLootDatabase.bySpec[specID] and KeyLab.GearLootDatabase.bySpec[specID][sourceID]
    local out = {}
    for _, itemID in ipairs(ids or {}) do
        local item = KeyLab.GearLootDatabase.items[itemID]
        if item then table.insert(out, item) end
    end
    return out
end

function KeyLab.GearLootDatabase.GetItemsForSpecDungeon(specID, sourceID)
    return KeyLab.GearLootDatabase.GetItemsForSpecSource(specID, sourceID)
end

function KeyLab.GearLootDatabase.IsDualWieldEligible(itemID, specID)
    return KeyLab.GearLootDatabase.dualWieldBySpec
        and KeyLab.GearLootDatabase.dualWieldBySpec[itemID]
        and KeyLab.GearLootDatabase.dualWieldBySpec[itemID][specID] == true
        or false
end

function KeyLab.GearLootDatabase.GetItemStats(itemID, specID)
    return KeyLab.GearLootDatabase.statsBySpec
        and KeyLab.GearLootDatabase.statsBySpec[itemID]
        and KeyLab.GearLootDatabase.statsBySpec[itemID][specID]
        or nil
end

function KeyLab.GearLootDatabase.GetSeasonInfo()
    return KeyLab.GearLootDatabase.expansion, KeyLab.GearLootDatabase.season, KeyLab.GearLootDatabase.seasonName
end
